    /// </summary>
    public PageTask<C.Transfer, C.TransferList> ListAsync(C.TransfersListQuery? query = null, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _core.RequestPage<C.Transfer, C.TransferList>(Operations.ConnectTransfersList, new RequestArgs().WithQuery(query), options, cancellationToken);

    /// <summary>
    /// Release a plan and send it
    /// <para>
    /// Takes a plan and the release of the person who reviewed it. Answers 202 at once; the hub delivers when online. Poll <c>transfers.get</c> or read events. Checks: licence, grant, role, practitioner link, plan age and adapter version, dedupe.
    /// </para>
    /// <para>
    /// <c>POST /v1/connect/transfers</c>, scope <c>connect.transfer</c>, answers hold patient data, metered as <c>connect.transfer</c>, Idempotency-Key required (the SDK makes one).
    /// </para>
    /// </summary>
    public Task<C.Transfer> CreateAsync(C.TransferCreate body, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _core.RequestAsync<C.Transfer>(Operations.ConnectTransfersCreate, new RequestArgs().WithBody(body), options, cancellationToken);

    /// <summary>
    /// Get the status of a transfer
    /// <para>
    /// <c>GET /v1/connect/transfers/{transfer_id}</c>, scope <c>connect.read</c>.
    /// </para>
    /// </summary>
    public Task<C.Transfer> GetAsync(string transferId, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _core.RequestAsync<C.Transfer>(Operations.ConnectTransfersGet, new RequestArgs().Path("transfer_id", transferId), options, cancellationToken);

    /// <summary>
    /// Settle an <c>in_doubt</c> or <c>failed</c> transfer
    /// <para>
    /// A person checked the target system: <c>mark_done</c> if the entry is there, <c>resend</c> to send it again, <c>mark_failed</c> to give it up. The answer is the settled transfer, or for <c>resend</c> the new one. A <c>failed</c> transfer is parked on the hub too: <c>mark_done</c> and <c>mark_failed</c> unpark it there; it has no release any more, so <c>resend</c> answers 409 and the note is released again. The PDFs of the plan (<c>uploads.create</c>) stay until the transfer's <c>expires_at</c>; a <c>resend</c> after they are gone answers 409 <c>uploads_gone</c>, and the transfer stays as it was. <c>resolved_by</c> is an active doctor or site admin; another role gets 403 <c>forbidden</c> with <c>reason</c> <c>role</c>.
    /// </para>
    /// <para>
    /// <c>POST /v1/connect/transfers/{transfer_id}/resolve</c>, scope <c>connect.transfer</c>.
    /// </para>
    /// </summary>
    public Task<C.Transfer> ResolveAsync(string transferId, C.TransferResolve body, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _core.RequestAsync<C.Transfer>(Operations.ConnectTransfersResolve, new RequestArgs().Path("transfer_id", transferId).WithBody(body), options, cancellationToken);

    /// <summary>
    /// Helper, no API operation: reads the transfer until it is final or in_doubt, or until the <c>until</c> check holds.
    /// </summary>
    public Task<C.Transfer> WaitAsync(string transferId, TransferWaitOptions? options = null, CancellationToken cancellationToken = default)
        => Waits.TransferAsync((i, ct) => GetAsync(i, null, ct), transferId, options ?? new TransferWaitOptions(), _core.Sleep, cancellationToken);
}

